BEGIN;
CREATE TABLE ad_goal(id uuid PRIMARY KEY,organization_id text NOT NULL,workspace_id text NOT NULL,project_id text NOT NULL,title text NOT NULL,description text NOT NULL,source text NOT NULL,status text NOT NULL,idempotency_key text NOT NULL,request_fingerprint text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,workspace_id,project_id,idempotency_key));
CREATE TABLE ad_task(id uuid PRIMARY KEY,organization_id text NOT NULL,workspace_id text NOT NULL,goal_id uuid NOT NULL REFERENCES ad_goal(id),project_id text NOT NULL,task_key text NOT NULL,title text NOT NULL,description text NOT NULL,priority text NOT NULL,risk_level text NOT NULL,status text NOT NULL,max_attempts integer NOT NULL DEFAULT 3,required_capabilities jsonb NOT NULL DEFAULT '[]',output jsonb NOT NULL DEFAULT '{}',metadata jsonb NOT NULL DEFAULT '{}',ready_at timestamptz,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(goal_id,task_key),UNIQUE(goal_id,id));
CREATE TABLE ad_task_dependency(id uuid PRIMARY KEY,goal_id uuid NOT NULL REFERENCES ad_goal(id),task_id uuid NOT NULL,depends_on_task_id uuid NOT NULL,dependency_type text NOT NULL,required_status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(task_id<>depends_on_task_id),FOREIGN KEY(goal_id,task_id) REFERENCES ad_task(goal_id,id),FOREIGN KEY(goal_id,depends_on_task_id) REFERENCES ad_task(goal_id,id),UNIQUE(task_id,depends_on_task_id,dependency_type));
CREATE TABLE ad_task_attempt(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES ad_task(id),attempt_number integer NOT NULL,status text NOT NULL,worker_id uuid,lease_id uuid,artifact_refs jsonb NOT NULL DEFAULT '[]',commit_hash text,validation_result jsonb NOT NULL DEFAULT '{}',metadata jsonb NOT NULL DEFAULT '{}',started_at timestamptz,heartbeat_at timestamptz,finished_at timestamptz,UNIQUE(task_id,attempt_number));
CREATE TABLE ad_planner_submission(id uuid PRIMARY KEY,goal_id uuid NOT NULL REFERENCES ad_goal(id),planner_version text NOT NULL,graph_fingerprint text NOT NULL,source_artifact_ref text,graph_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(goal_id,planner_version));
CREATE TABLE ad_worker(id uuid PRIMARY KEY,organization_id text NOT NULL,workspace_id text NOT NULL,worker_key text NOT NULL,name text NOT NULL,runtime_type text NOT NULL,status text NOT NULL,capabilities jsonb NOT NULL DEFAULT '[]',max_concurrency integer NOT NULL,active_claims integer NOT NULL DEFAULT 0,last_heartbeat_at timestamptz NOT NULL DEFAULT now(),metadata jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,workspace_id,worker_key));
CREATE TABLE ad_worker_session(id uuid PRIMARY KEY,worker_id uuid NOT NULL REFERENCES ad_worker(id),session_id uuid NOT NULL UNIQUE,status text NOT NULL,started_at timestamptz NOT NULL,last_heartbeat_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,ended_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1);
CREATE TABLE ad_task_lease(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES ad_task(id),attempt_id uuid NOT NULL REFERENCES ad_task_attempt(id),worker_id uuid NOT NULL REFERENCES ad_worker(id),session_id uuid NOT NULL REFERENCES ad_worker_session(session_id),lease_token text NOT NULL,fencing_token bigint NOT NULL,status text NOT NULL,acquired_at timestamptz NOT NULL,heartbeat_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,released_at timestamptz,version integer NOT NULL DEFAULT 1,UNIQUE(task_id,fencing_token));
CREATE UNIQUE INDEX ad_task_one_active_lease ON ad_task_lease(task_id) WHERE status='ACTIVE';
CREATE TABLE ad_outbox_event(event_id uuid PRIMARY KEY,event_type text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version integer NOT NULL,goal_id uuid REFERENCES ad_goal(id),project_id text,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE TABLE ad_state_transition(id uuid PRIMARY KEY,transition_key text NOT NULL UNIQUE,entity_type text NOT NULL,entity_id uuid NOT NULL,goal_id uuid REFERENCES ad_goal(id),project_id text,actor_type text NOT NULL,actor_id text NOT NULL,previous_status text NOT NULL,next_status text NOT NULL,reason_code text NOT NULL,entity_version integer NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ad_task_queue_scan ON ad_task(organization_id,workspace_id,status,priority,ready_at,created_at,task_key);
CREATE INDEX ad_lease_expiry ON ad_task_lease(status,expires_at);
CREATE INDEX ad_outbox_unpublished ON ad_outbox_event(created_at) WHERE published_at IS NULL;
COMMIT;
